const n='<div id="container">\n    <div id="canvas-container">\n        <div id="top-control-bar">\n            <div class="control-bar-section">\n                \x3c!-- <button class="control-button active" id="show-visual" data-checked="true">\n                    <span data-i18n="visual"></span>\n                </button> --\x3e\n                <button class="control-button" id="show-collision" data-checked="false">\n                    <span data-i18n="collision"></span>\n                </button>\n                <button class="control-button" id="show-inertia" data-checked="false">\n                    <span data-i18n="inertia"></span>\n                </button>\n                <button class="control-button" id="show-com" data-checked="false">\n                    <span data-i18n="com"></span>\n                </button>\n                <button class="control-button" id="toggle-axes-btn" data-checked="false">\n                    <span data-i18n="axes"></span>\n                </button>\n                <button class="control-button" id="toggle-joint-axes-btn" data-checked="false">\n                    <span data-i18n="jointAxes"></span>\n                </button>\n                <button class="control-button active" id="toggle-shadow" data-checked="true">\n                    <span data-i18n="shadow"></span>\n                </button>\n                <button class="control-button active" id="toggle-lighting" data-checked="true">\n                    <span data-i18n="lighting"></span>\n                </button>\n            </div>\n\n            <div class="control-bar-divider"></div>\n\n            <div class="control-bar-section">\n                <select id="up-select" class="control-bar-select">\n                    <option value="+Z">+Z</option>\n                    <option value="-Z">-Z</option>\n                    <option value="+Y">+Y</option>\n                    <option value="-Y">-Y</option>\n                    <option value="+X">+X</option>\n                    <option value="-X">-X</option>\n                </select>\n            </div>\n\n            <div class="control-bar-divider"></div>\n\n                <button class="tool-button active" id="toggle-history-panel">\n                    <span class="tool-button-text" data-i18n="history"></span>\n                </button>\n\n                <button class="tool-button" id="toggle-joints-panel">\n                    <span class="tool-button-text" data-i18n="joints"></span>\n                </button>\n\n            <div class="control-bar-divider"></div>\n\n            <div class="control-bar-section">\n                <button class="tool-button" id="help-button">\n                    <span class="tool-button-text" data-i18n="help"></span>\n                </button>\n                <button class="tool-button" id="language-toggle">\n                    <span class="tool-button-text" data-i18n="language"></span>\n                </button>\n                <button class="tool-button" id="theme-toggle">\n                    <span class="tool-button-icon">🌙</span>\n                </button>\n            </div>\n        </div>\n\n        <div id="mujoco-simulation-bar" style="display:none;">\n            <button id="mujoco-reset-btn-bar">\n                <span data-i18n="mujocoReset"></span>\n            </button>\n            <button id="mujoco-simulate-btn-bar">\n                <span data-i18n="mujocoSimulate"></span>\n            </button>\n        </div>\n\n        <canvas id="canvas"></canvas>\n\n        \x3c!-- 左侧操作控制面板 --\x3e\n        <div id="floating-control-panel" class="floating-panel">\n            <div class="floating-panel-header">\n                <span data-i18n="controlPanel"></span>\n                <div class="control-panel-header-actions">\n                    <button class="panel-close-btn" data-panel="floating-control-panel">✕</button>\n                </div>\n            </div>\n            <div class="floating-panel-content control-panel-content">\n                \x3c!-- 遥操作 --\x3e\n                <div class="control-section">\n                    <div class="control-section-header">\n                        <span class="control-section-title" data-i18n="teleoperation"></span>\n                    </div>\n                    <div class="control-section-body">\n                        <button class="control-icon-btn" id="teleop-icon-btn" data-active="false">\n                            <svg class="control-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">\n                                <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/>\n                            </svg>\n                        </button>\n                        <button class="control-action-btn" id="teleop-start-btn" data-running="false">\n                            <span data-i18n="start"></span>\n                        </button>\n                    </div>\n                </div>\n                <div class="control-section-divider"></div>\n                \x3c!-- 动作录制 --\x3e\n                <div class="control-section">\n                    <div class="control-section-header">\n                        <span class="control-section-title" data-i18n="actionRecord"></span>\n                    </div>\n                    <div class="control-section-body">\n                        <button class="control-icon-btn" id="record-icon-btn" data-active="false">\n                            <svg class="control-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">\n                                <circle cx="12" cy="12" r="10"/>\n                                <circle cx="12" cy="12" r="4" fill="currentColor"/>\n                            </svg>\n                        </button>\n                        <button class="control-action-btn" id="record-start-btn" data-running="false">\n                            <span data-i18n="start"></span>\n                        </button>\n                    </div>\n                </div>\n                <div class="control-section-divider"></div>\n                \x3c!-- 数据采集 --\x3e\n                <div class="control-section">\n                    <div class="control-section-header">\n                        <span class="control-section-title" data-i18n="dataCollection"></span>\n                    </div>\n                    <div class="control-section-body">\n                        <button class="control-icon-btn" id="collect-icon-btn" data-active="false">\n                            <svg class="control-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">\n                                <path d="M20 6L9 17l-5-5"/>\n                                <path d="M4 12v8h16v-8"/>\n                                <path d="M12 3v9"/>\n                            </svg>\n                        </button>\n                        <button class="control-action-btn" id="collect-start-btn" data-running="false">\n                            <span data-i18n="start"></span>\n                        </button>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div id="floating-joints-panel" class="floating-panel maximized" style="display: none;">\n            <div class="floating-panel-header">\n                <span data-i18n="jointControl"></span>\n                <div class="joints-panel-controls">\n                    <div id="unit-toggle">\n                        <button id="unit-rad" class="active" data-i18n="radian"></button>\n                        <button id="unit-deg" data-i18n="degree"></button>\n                    </div>\n                    <button class="control-button" id="apply-joint-dict-btn" title="Apply joint dictionary">\n                        <span data-i18n="jointSet"></span>\n                    </button>\n                    <button class="control-button" id="reset-joints-btn">\n                        <span data-i18n="reset"></span>\n                    </button>\n                    <button class="control-button active" id="ignore-limits" data-checked="true">\n                        <span data-i18n="limits"></span>\n                    </button>\n                    <button class="panel-maximize-btn" data-panel-id="floating-joints-panel">⛶</button>\n                    <button class="panel-close-btn" data-panel="floating-joints-panel">✕</button>\n                </div>\n            </div>\n            <div class="floating-panel-content" id="joint-controls">\n                <div class="empty-state" data-i18n="noModel"></div>\n            </div>\n        </div>\n\n        <div id="floating-history-panel" class="floating-panel maximized">\n            <div class="floating-panel-header">\n                <span data-i18n="historyPanel"></span>\n                <div class="history-panel-controls">\n                    <button class="panel-maximize-btn" data-panel-id="floating-history-panel">⛶</button>\n                    <button class="panel-close-btn" data-panel="floating-history-panel">✕</button>\n                </div>\n            </div>\n            <div class="floating-panel-content history-panel-content">\n                \x3c!-- 动作录制历史 --\x3e\n                <div class="history-section">\n                    <div class="history-section-header">\n                        <span class="history-section-title" data-i18n="recordHistory"></span>\n                        <button class="history-more-btn" data-target-tab="record" data-i18n="more"></button>\n                    </div>\n                    <div class="history-list" id="record-history-list">\n                        <div class="history-empty" data-i18n="noRecordHistory"></div>\n                    </div>\n                </div>\n                \x3c!-- 数据采集历史 --\x3e\n                <div class="history-section">\n                    <div class="history-section-header">\n                        <span class="history-section-title" data-i18n="collectHistory"></span>\n                        <button class="history-more-btn" data-target-tab="label" data-i18n="more"></button>\n                    </div>\n                    <div class="history-list" id="collect-history-list">\n                        <div class="history-empty" data-i18n="noCollectHistory"></div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div id="drop-zone">\n            <div id="drop-text">\n                <strong data-i18n="dropHint"></strong><br>\n                <span style="font-size: 12px; margin-top: 8px; display: block;" data-i18n="dropHintSub"></span>\n            </div>\n        </div>\n\n        <div id="hover-info">\n            <div id="hover-link-name"></div>\n            <div id="hover-joint-name"></div>\n            <div id="hover-link-mass"></div>\n            <div id="hover-merged-links"></div>\n        </div>\n\n        <div id="floating-help-panel" class="floating-panel" style="display: none;">\n            <div class="floating-panel-header">\n                <span data-i18n="helpTitle">Robot Insight v1.0.0</span>\n                <button class="panel-close-btn" data-panel="floating-help-panel">✕</button>\n            </div>\n            <div class="floating-panel-content">\n                <div class="help-section">\n                    <div class="help-section-title" data-i18n="about"></div>\n                    <div class="help-section-content">\n                        <p data-i18n="aboutContent"></p>\n                        <div class="help-action-buttons">\n                            <a href="https://github.com/fan-ziqi/robot_viewer" target="_blank" rel="noopener" class="help-action-btn">\n                                <svg style="width: 14px; height: 14px; margin-right: 6px; fill: currentColor; vertical-align: middle;" viewBox="0 0 16 16">\n                                    <path d="M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82.64-.18 1.32-.27 2-.27.68 0 1.36.09 2 .27 1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.013 8.013 0 0016 8c0-4.42-3.58-8-8-8z"/>\n                                </svg>\n                                <span data-i18n="projectHome"></span>\n                            </a>\n                            <a href="mailto:fanziqi614@gmail.com" class="help-action-btn">\n                                <svg style="width: 14px; height: 14px; margin-right: 6px; fill: currentColor; vertical-align: middle;" viewBox="0 0 16 16">\n                                    <path d="M0 4a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H2a2 2 0 0 1-2-2V4zm2-1a1 1 0 0 0-1 1v.217l7 4.2 7-4.2V4a1 1 0 0 0-1-1H2zm13 2.383l-4.758 2.855L15 11.114v-5.73zm-.034 6.878L9.271 8.82 8 9.583 6.728 8.82l-5.694 3.44A1 1 0 0 0 2 13h12a1 1 0 0 0 .966-.739zM1 11.114l4.758-2.876L1 5.383v5.73z"/>\n                                </svg>\n                                <span data-i18n="email">Email</span>\n                            </a>\n                            <a href="https://github.com/fan-ziqi" target="_blank" rel="noopener" class="help-action-btn">\n                                <svg style="width: 14px; height: 14px; margin-right: 6px; fill: currentColor; vertical-align: middle;" viewBox="0 0 16 16">\n                                    <path d="M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82.64-.18 1.32-.27 2-.27.68 0 1.36.09 2 .27 1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.013 8.013 0 0016 8c0-4.42-3.58-8-8-8z"/>\n                                </svg>\n                                <span data-i18n="githubProfile">GitHub Profile</span>\n                            </a>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div id="code-editor-panel" class="floating-panel">\n            <div class="code-editor-header">\n                <div class="code-editor-title">\n                    <span data-i18n="codeEditor"></span>\n                </div>\n                <div class="code-editor-actions">\n                    <button class="code-editor-btn" id="reload-btn" data-i18n="reload"></button>\n                    <button class="code-editor-btn primary" id="save-btn" data-i18n="download"></button>\n                </div>\n                <button class="panel-maximize-btn" data-panel-id="code-editor-panel">⛶</button>\n                <button class="panel-close-btn" id="close-editor-btn">✕</button>\n            </div>\n            <div class="code-editor-info-bar">\n                <input type="text" class="code-editor-filename-input" id="editor-filename-input" placeholder="newfile.xml" />\n                <span class="code-editor-filename" id="editor-filename" data-i18n="noFileOpen"></span>\n                <span class="code-editor-save-status saved" id="editor-save-status" data-i18n="saved"></span>\n            </div>\n            <div id="code-editor-content">\n                <div id="code-editor-wrapper" style="height: 100%;"></div>\n            </div>\n        </div>\n    </div>\n</div>\n\n<div id="bottom-help-bar">\n    <div class="bottom-help-item">\n        <span class="bottom-help-key" data-i18n="leftDrag"></span>\n        <span data-i18n="rotateView"></span>\n    </div>\n    <div class="bottom-help-separator"></div>\n    <div class="bottom-help-item">\n        <span class="bottom-help-key" data-i18n="rightDrag"></span>\n    </div>\n    <div class="bottom-help-separator"></div>\n    <div class="bottom-help-item">\n        <span class="bottom-help-key" data-i18n="scroll"></span>\n        <span data-i18n="zoom"></span>\n    </div>\n    <div class="bottom-help-separator"></div>\n    <div class="bottom-help-item">\n        <span class="bottom-help-key" data-i18n="clickModel"></span>\n        <span data-i18n="controlJoint"></span>\n    </div>\n</div>\n\n\x3c!-- Joint dictionary modal (theme-consistent with existing help dialog) --\x3e\n<div id="joint-dict-dialog" class="github-help-dialog" aria-hidden="true">\n    <div class="help-dialog-content">\n        <div class="help-dialog-header">\n            <h3 data-i18n="applyJointDictTitle">Apply Joint Dictionary</h3>\n            <button id="joint-dict-close" class="help-dialog-close">✕</button>\n        </div>\n        <div class="help-dialog-body">\n            \x3c!-- Tabs --\x3e\n            <div class="joint-dict-tabs">\n                <button class="joint-dict-tab-btn active" data-tab="dict">Dictionary</button>\n                <button class="joint-dict-tab-btn" data-tab="table">Table</button>\n                <button class="joint-dict-tab-btn" data-tab="animation">Animation</button>\n            </div>\n\n            \x3c!-- Tab 1: Dictionary Mode --\x3e\n            <div class="joint-dict-tab-content active" data-tab-content="dict">\n                <p style="color:var(--text-secondary);font-size:13px;margin:0 0 12px 0;">Paste a JSON object mapping joint names to values:</p>\n                <textarea id="joint-dict-input" class="github-path-input" rows="8" placeholder=\'{"hip_roll_l_joint":0.5,"hip_pitch_l_joint":1}\'></textarea>\n                <div class="help-section" style="margin-top:12px;">\n                    <p style="font-size:12px;margin:4px 0;">Examples:</p>\n                    <p style="font-size:11px;margin:4px 0;"><code>{"shoulder": 0.5, "elbow": -0.3}</code></p>\n                </div>\n            </div>\n\n            \x3c!-- Tab 2: Table Mode --\x3e\n            <div class="joint-dict-tab-content" data-tab-content="table">\n                <p style="color:var(--text-secondary);font-size:13px;margin:0 0 12px 0;">Paste joint array and value array with unit type:</p>\n                <textarea id="joint-table-input" class="github-path-input" rows="8" placeholder=\'{"joint":["hip_roll_l_joint","hip_pitch_l_joint"],"value":[0.5,1],"valueType":"radians"}\'></textarea>\n                <div class="help-section" style="margin-top:12px;">\n                    <p style="font-size:12px;margin:4px 0;">valueType: "radians" or "degrees"</p>\n                </div>\n            </div>\n\n            \x3c!-- Tab 3: Animation Mode --\x3e\n            <div class="joint-dict-tab-content" data-tab-content="animation">\n                <p style="color:var(--text-secondary);font-size:13px;margin:0 0 8px 0;">Load from file or paste JSON:</p>\n                <div style="display:flex;gap:8px;margin-bottom:12px;">\n                    <input type="file" id="joint-animation-file" accept=".json" style="flex:1;padding:8px;background:var(--glass-border);border:1px solid var(--glass-border);border-radius:8px;color:var(--text-primary);font-size:13px;" />\n                </div>\n                <textarea id="joint-animation-input" class="github-path-input" rows="6" placeholder=\'{"joint":["joint1","joint2"],"value":[[0.1,0.2],[0.5,0.8]],"fps":30,"loop":1,"valueType":"radians"}\'></textarea>\n                <div style="display:flex;gap:12px;align-items:center;margin-top:12px;">\n                    <label style="color:var(--text-secondary);font-size:13px;">Loop count:</label>\n                    <input type="number" id="joint-animation-loop" min="1" value="1" style="width:80px;padding:6px 10px;background:var(--glass-border);border:1px solid var(--glass-border);border-radius:6px;color:var(--text-primary);font-size:13px;" />\n                    <span style="color:var(--text-tertiary);font-size:12px;">(default: 1)</span>\n                </div>\n                <div class="help-section" style="margin-top:12px;">\n                    <p style="font-size:12px;margin:4px 0;">Each row in value array is a keyframe. Add "loop" field in JSON or use input above.</p>\n                </div>\n            </div>\n\n            <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:16px;">\n                <button id="joint-dict-cancel-btn" class="help-dialog-close">Cancel</button>\n                <button id="joint-dict-apply-btn" class="github-load-btn">Apply</button>\n            </div>\n        </div>\n    </div>\n</div>';export{n as default};
